"""Reader for the accuracy -> djpower-ratio table generated by build_accuracy_table.py.

The table is loaded once per process and cached. Lookups are exact for the 0.01 accuracy grid
the table stores (a user-specified accuracy such as 99.5 always lands on it); an accuracy with
more decimals is linearly interpolated between the two neighbouring grid points. Anything
outside the table falls back to the fitted curve in analyzer/data_analyzer.py, which is
also what the builder uses for grid points with no measured data.
"""
from __future__ import annotations

import csv
import os
from decimal import Decimal

from ... import api_handler
from ...analyzer.data_analyzer import djpower_calc_opt

TABLE_PATH = os.path.join(os.path.dirname(os.path.abspath(__file__)), "accuracy_ratio.csv")

_ROWS: list[tuple[float, Decimal, str]] | None = None


def table_path() -> str:
    return TABLE_PATH


def load(force: bool = False) -> list[tuple[float, Decimal, str]]:
    """The table as [(accuracy, ratio, source)], loaded once and cached."""
    global _ROWS
    if _ROWS is not None and not force:
        return _ROWS

    rows: list[tuple[float, Decimal, str]] = []
    if os.path.exists(TABLE_PATH):
        with open(TABLE_PATH, "r", encoding="utf-8", newline="") as f:
            lines = (line for line in f if not line.startswith("#"))
            for record in csv.DictReader(lines):
                rows.append((float(record["accuracy"]), Decimal(record["ratio"]), record["source"]))
    rows.sort(key=lambda row: row[0])
    _ROWS = rows
    return _ROWS


def build_if_missing(verbose: bool = True) -> bool:
    """Generate the table when it is not there yet. True when a build was performed."""
    if os.path.exists(TABLE_PATH):
        return False
    from . import build_accuracy_table

    if verbose:
        print(f"accuracy table missing, building {TABLE_PATH}")
    build_accuracy_table.main(["--source", os.path.join(api_handler.RECORDS_PATH, "full_varecord.json")])
    load(force=True)
    return True


def fit_ratio(accuracy: float) -> Decimal:
    """The fitted fallback curve, at a resolution where its own rounding is irrelevant."""
    return Decimal(str(float(djpower_calc_opt(accuracy, 1e7)) / 1e7))


def ratio_at(accuracy: float | Decimal) -> Decimal:
    """Ratio for an accuracy, from the table when possible and the fitted curve otherwise."""
    rows = load()
    value = float(accuracy)
    if not rows:
        return fit_ratio(value)

    first, last = rows[0][0], rows[-1][0]
    if value < first or value > last:
        return fit_ratio(value)

    # Exact grid hit (the normal case: accuracies come in with two decimals).
    for grid, ratio, _ in rows:
        if grid == value:
            return ratio
        if grid > value:
            break

    # Interpolate between the two neighbouring grid points.
    lower = rows[0]
    upper = rows[-1]
    for grid, ratio, _ in rows:
        if grid <= value:
            lower = (grid, ratio, "")
        if grid >= value:
            upper = (grid, ratio, "")
            break
    span = upper[0] - lower[0]
    if span <= 0:
        return lower[1]
    weight = Decimal(str((value - lower[0]) / span))
    return lower[1] + (upper[1] - lower[1]) * weight


def accuracy_for_ratio(target_ratio: float | Decimal) -> Decimal | None:
    """Smallest accuracy whose ratio reaches target_ratio (inverse lookup), None if out of range."""
    rows = load()
    if not rows:
        return None
    target = Decimal(str(target_ratio))
    if target > rows[-1][1]:
        return None
    if target <= rows[0][1]:
        return Decimal(str(rows[0][0]))
    lower = rows[0]
    for grid, ratio, _ in rows:
        if ratio >= target:
            span = ratio - lower[1]
            if span <= 0:
                return Decimal(str(grid))
            weight = (target - lower[1]) / span
            return (Decimal(str(lower[0])) + (Decimal(str(grid)) - Decimal(str(lower[0]))) * weight
                    ).quantize(Decimal("0.001"))
        lower = (grid, ratio, "")
    return None
